(6706382, 1003340, 3936, '<td valign="top">Printed large, this would be way cool!</td>', 'Printed large, this would be way cool!', '2012-03-10 18:38:09.000000', NULL, 1),
(6706384, 1003308, 3936, '<td valign="top">Ok, you got me. I cannot figure out what this is.  Looks like bits of ice, on an ice shaver, or a sea scheel, or who knows what.  I''m thinking I''d like to see it a little brighter, but still very nicely done!</td>', 'Ok, you got me. I cannot figure out what this is.  Looks like bits of ice, on an ice shaver, or a sea scheel, or who knows what.  I''m thinking I''d like to see it a little brighter, but still very nicely done!', '2012-03-10 18:41:50.000000', NULL, 1),
(6706385, 1003161, 10785, '<td valign="top">Great composition using the triangular shape with the strong base at the bottom. Good light, great bokeh good detail.</td>', 'Great composition using the triangular shape with the strong base at the bottom. Good light, great bokeh good detail.', '2012-03-10 18:43:28.000000', NULL, 1),
(6706458, 1002945, 3936, '<td valign="top">Nice contrasting point of color.  It makes this image pop.</td>', 'Nice contrasting point of color.  It makes this image pop.', '2012-03-10 21:00:27.000000', NULL, 1),
(6706459, 1003223, 3936, '<td valign="top">I really like the sharpness of the feather against the soft background.</td>', 'I really like the sharpness of the feather against the soft background.', '2012-03-10 21:02:15.000000', NULL, 1),
(6706460, 1002678, 3936, '<td valign="top">I''m thinking this is bread, whatever it is, I like it.</td>', 'I''m thinking this is bread, whatever it is, I like it.', '2012-03-10 21:05:36.000000', NULL, 1),
(6706465, 1003228, 3936, '<td valign="top">Love the texture and patterns in this one.  Monochrome was an excellent choice here.</td>', 'Love the texture and patterns in this one.  Monochrome was an excellent choice here.', '2012-03-10 21:11:09.000000', NULL, 1),
(6706466, 1003188, 3936, '<td valign="top">I''ve always liked plasma balls.  The effect here is excellent.</td>', 'I''ve always liked plasma balls.  The effect here is excellent.', '2012-03-10 21:12:21.000000', NULL, 1),
(6706467, 1003345, 3936, '<td valign="top">Very nice.  This almost comes up off the screen at you.  Great dimensional feel.  Love the texture.</td>', 'Very nice.  This almost comes up off the screen at you.  Great dimensional feel.  Love the texture.', '2012-03-10 21:14:35.000000', NULL, 1),
(6706468, 1002611, 3936, '<td valign="top">I was trying to figure out what this was, or how it was done.  The title says it all.  A Gallilean slow thermometer.  Love the colors shapes and detail.</td>', 'I was trying to figure out what this was, or how it was done.  The title says it all.  A Gallilean slow thermometer.  Love the colors shapes and detail.', '2012-03-10 21:17:47.000000', NULL, 1),
(6706470, 1002441, 3936, '<td valign="top">Not sure if you will not wind up losing some points to people who do not see this as abstract.  But it is a very well done high key image.  I could see this in a gallery setting quite easily. 8</td>', 'Not sure if you will not wind up losing some points to people who do not see this as abstract.  But it is a very well done high key image.  I could see this in a gallery setting quite easily. 8', '2012-03-10 21:21:25.000000', NULL, 1),
(6706474, 1003156, 3936, '<td valign="top">For some reason this just makes me say, "Lady bug, lady bug, fly away home.  Your house is on fire, and your shildrean are alone."  I am drawn to the dot in the center.  It looks like a little world within a world.  Very nice work.</td>', 'For some reason this just makes me say, "Lady bug, lady bug, fly away home.  Your house is on fire, and your shildrean are alone."  I am drawn to the dot in the center.  It looks like a little world within a world.  Very nice work.', '2012-03-10 21:24:23.000000', NULL, 1),
(6706478, 1002286, 3936, '<td valign="top">Whatever this is, I like it.</td>', 'Whatever this is, I like it.', '2012-03-10 21:27:53.000000', NULL, 1),
