(6709098, 1003323, 142473, '<td valign="top">I really love this image.  Good use of ''thirds''.  The line in the back really makes the image.</td>', 'I really love this image.  Good use of ''thirds''.  The line in the back really makes the image.', '2012-03-13 20:00:24.000000', NULL, 1),
(6709100, 1002611, 142473, '<td valign="top">Good use of macro for an abstract effect.  Without your title, I probably wouldn''t have been able to guess it.</td>', 'Good use of macro for an abstract effect.  Without your title, I probably wouldn''t have been able to guess it.', '2012-03-13 20:01:33.000000', NULL, 1),
(6709102, 1002113, 142473, '<td valign="top">Missing some clarity and contrast, in my opinion.</td>', 'Missing some clarity and contrast, in my opinion.', '2012-03-13 20:02:13.000000', NULL, 1),
