(6709128, 1002962, 142473, '<td valign="top">Nice image.  Clean focus.  Cool colors.</td>', 'Nice image.  Clean focus.  Cool colors.', '2012-03-13 20:26:14.000000', NULL, 1),
(6709208, 1003323, 140305, '<td valign="top">No idea what it is, but I love it!</td>', 'No idea what it is, but I love it!', '2012-03-13 21:48:38.000000', NULL, 1),
(6709397, 1002486, 142837, '<td valign="top">The framing is great, but while it meets the macro category, I don''t see it as abstract.  I do like how extremely shallow DOF, and how you can even see the detail in the surface the pennies is sitting on.</td>', 'The framing is great, but while it meets the macro category, I don''t see it as abstract.  I do like how extremely shallow DOF, and how you can even see the detail in the surface the pennies is sitting on.', '2012-03-14 00:52:17.000000', NULL, 1),
(6709399, 1003326, 142837, '<td valign="top">This is a cool concept.  I can tell its a fork, piercing through a liquid surface.  Nice capture.  It was quick enough to catch the surface tension of the liquid being broken, but before ripples spread out to far.  While I can tell what the object is, it is an unusual way to see a fork, and still meets the abstract part of the challenge.</td>', 'This is a cool concept.  I can tell its a fork, piercing through a liquid surface.  Nice capture.  It was quick enough to catch the surface tension of the liquid being broken, but before ripples spread out to far.  While I can tell what the object is, it is an unusual way to see a fork, and still meets the abstract part of the challenge.', '2012-03-14 00:56:43.000000', NULL, 1),
(6709401, 1003222, 142837, '<td valign="top">Nice title.  At my job we juice lemonade daily, and I never really associated the similarities between a jet turbine and a juice reamer... that is, until now.</td>', 'Nice title.  At my job we juice lemonade daily, and I never really associated the similarities between a jet turbine and a juice reamer... that is, until now.', '2012-03-14 00:59:13.000000', NULL, 1),
