(6710287, 1002996, 138630, '<td valign="top">Gorgeous color, graceful lines, excellent clarity.  One of my top ten images.</td>', 'Gorgeous color, graceful lines, excellent clarity.  One of my top ten images.', '2012-03-14 21:33:55.000000', NULL, 1),
(6710293, 1003191, 138630, '<td valign="top">I admire the grace, composition, lighting and lines here.  Not as crazy about the colors but it''s still one of my top ten images.</td>', 'I admire the grace, composition, lighting and lines here.  Not as crazy about the colors but it''s still one of my top ten images.', '2012-03-14 21:36:55.000000', NULL, 1),
(6710296, 1003312, 138630, '<td valign="top">I really like the way these "tentacles" burst out from a center.  Colors are nice for that , too.  Wish it didn''t fall off in the upper left but it''s still one of my top ten images.</td>', 'I really like the way these "tentacles" burst out from a center.  Colors are nice for that , too.  Wish it didn''t fall off in the upper left but it''s still one of my top ten images.', '2012-03-14 21:39:04.000000', NULL, 1),
(6710297, 1003188, 138630, '<td valign="top">This fascinates me -- I''ve been bumping it all day :)  No idea what it is but I love the pink and purple together and they are so nice on the black.  Cool title - I thought of a comet or shooting star or something, too.  A top pick.</td>', 'This fascinates me -- I''ve been bumping it all day :)  No idea what it is but I love the pink and purple together and they are so nice on the black.  Cool title - I thought of a comet or shooting star or something, too.  A top pick.', '2012-03-14 21:40:42.000000', NULL, 1),
(6710298, 1003203, 138630, '<td valign="top">Gorgeous colors, light, clarity and detail.  Nice title, too.  One of my favorites in the challenge.</td>', 'Gorgeous colors, light, clarity and detail.  Nice title, too.  One of my favorites in the challenge.', '2012-03-14 21:41:31.000000', NULL, 1),
(6710299, 1003296, 138630, '<td valign="top">I know this is glass, probably an art glass bowl.  I have one (nothing like this - finer and completely different colors) and I tried and tried to get a good macro of it for this challenge.  Finally gave up.  You have done so well with everything I struggled with: light, focus and composition.</td>', 'I know this is glass, probably an art glass bowl.  I have one (nothing like this - finer and completely different colors) and I tried and tried to get a good macro of it for this challenge.  Finally gave up.  You have done so well with everything I struggled with: light, focus and composition.', '2012-03-14 21:43:29.000000', NULL, 1),
(6710300, 1003342, 138630, '<td valign="top">Must admit that the blue and yellow palette got me early on -- my favorite.  This is very nicely focused and beautifully clear.  Well done.  One of my top ten.</td>', 'Must admit that the blue and yellow palette got me early on -- my favorite.  This is very nicely focused and beautifully clear.  Well done.  One of my top ten.', '2012-03-14 21:44:34.000000', NULL, 1),
(6710303, 1003222, 138630, '<td valign="top">Without the title I would never have guessed as I don''t have one of these.  Not that it mattered to me that you "gave it away" - it''s a lovely composition with great lines and shapes and one of my top ten.</td>', 'Without the title I would never have guessed as I don''t have one of these.  Not that it mattered to me that you "gave it away" - it''s a lovely composition with great lines and shapes and one of my top ten.', '2012-03-14 21:45:53.000000', NULL, 1),
(6710353, 1003204, 19825, '<td valign="top">Interesting unidentifiable halo. I like it.</td>', 'Interesting unidentifiable halo. I like it.', '2012-03-14 22:31:30.000000', NULL, 1),
